{
  "name": "VXI-11网络测试仪器",
  "name_en": "VXI-11 Network Test Instrument",
  "manufacturer": "",
  "description": "支持 VXI-11 协议的以太网测试测量仪器，如示波器、信号源、频谱分析仪或数字万用表等。此类仪器可通过局域网接入实验室自动化系统，用于远程发送命令、读取测量数据、触发采集、读取状态以及进行远程/本地控制切换。",
  "description_en": "A LAN-connected test and measurement instrument that supports the VXI-11 protocol, such as an oscilloscope, signal generator, spectrum analyzer, or digital multimeter. These instruments are used in laboratory automation for remote command and data transfer, triggering, status reading, and switching between remote and local control.",
  "tag_hints": [
    "VXI-11",
    "LAN instrument control",
    "SCPI over Ethernet",
    "test and measurement",
    "remote instrument control",
    "status byte reading",
    "instrument triggering"
  ],
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到VXI-11网络仪器",
      "description_en": "Connect to the VXI-11 network instrument."
    },
    {
      "action_name": "auto-create_intr_chan",
      "description": "创建仪器服务请求中断通道",
      "description_en": "Create an interrupt channel for instrument service requests."
    },
    {
      "action_name": "auto-create_link",
      "description": "创建与仪器的逻辑通信链路",
      "description_en": "Create a logical communication link to the instrument."
    },
    {
      "action_name": "auto-destroy_intr_chan",
      "description": "关闭仪器服务请求中断通道",
      "description_en": "Close the interrupt channel for instrument service requests."
    },
    {
      "action_name": "auto-destroy_link",
      "description": "销毁与仪器的逻辑通信链路",
      "description_en": "Destroy the logical communication link to the instrument."
    },
    {
      "action_name": "auto-device_clear",
      "description": "清除仪器状态或缓冲内容",
      "description_en": "Clear the instrument state or buffers."
    },
    {
      "action_name": "auto-device_docmd",
      "description": "执行仪器的底层设备命令",
      "description_en": "Execute a low-level device-specific command on the instrument."
    },
    {
      "action_name": "auto-device_enable_srq",
      "description": "启用或禁用仪器服务请求通知",
      "description_en": "Enable or disable instrument service request notifications."
    },
    {
      "action_name": "auto-device_local",
      "description": "将仪器切换到本地面板控制",
      "description_en": "Return the instrument to local front-panel control."
    },
    {
      "action_name": "auto-device_lock",
      "description": "锁定仪器以进行独占控制",
      "description_en": "Lock the instrument for exclusive control."
    },
    {
      "action_name": "auto-device_read",
      "description": "从仪器读取数据",
      "description_en": "Read data from the instrument."
    },
    {
      "action_name": "auto-device_read_stb",
      "description": "读取仪器状态字节",
      "description_en": "Read the instrument status byte."
    },
    {
      "action_name": "auto-device_remote",
      "description": "将仪器切换到远程控制模式",
      "description_en": "Place the instrument into remote control mode."
    },
    {
      "action_name": "auto-device_trigger",
      "description": "向仪器发送触发信号",
      "description_en": "Send a trigger to the instrument."
    },
    {
      "action_name": "auto-device_unlock",
      "description": "解除仪器独占锁定",
      "description_en": "Release the instrument lock."
    },
    {
      "action_name": "auto-device_write",
      "description": "向仪器写入命令或数据",
      "description_en": "Write commands or data to the instrument."
    },
    {
      "action_name": "auto-pack_device_link",
      "description": "打包仪器链路标识参数",
      "description_en": "Pack the instrument link identifier parameters."
    },
    {
      "action_name": "auto-pack_create_link_parms",
      "description": "打包创建仪器链路所需参数",
      "description_en": "Pack the parameters required to create an instrument link."
    },
    {
      "action_name": "auto-pack_device_write_parms",
      "description": "打包向仪器写入数据的参数",
      "description_en": "Pack the parameters for writing data to the instrument."
    },
    {
      "action_name": "auto-pack_device_read_parms",
      "description": "打包从仪器读取数据的参数",
      "description_en": "Pack the parameters for reading data from the instrument."
    },
    {
      "action_name": "auto-pack_device_generic_parms",
      "description": "打包通用仪器操作参数",
      "description_en": "Pack generic instrument operation parameters."
    },
    {
      "action_name": "auto-pack_device_remote_func_parms",
      "description": "打包仪器远程功能控制参数",
      "description_en": "Pack the parameters for instrument remote-function control."
    },
    {
      "action_name": "auto-pack_device_enable_srq_parms",
      "description": "打包服务请求使能参数",
      "description_en": "Pack the parameters for enabling service requests."
    },
    {
      "action_name": "auto-pack_device_lock_parms",
      "description": "打包仪器锁定参数",
      "description_en": "Pack the parameters for instrument locking."
    },
    {
      "action_name": "auto-pack_device_docmd_parms",
      "description": "打包设备命令执行参数",
      "description_en": "Pack the parameters for executing a device command."
    },
    {
      "action_name": "auto-unpack_device_link",
      "description": "解析仪器链路标识",
      "description_en": "Unpack the instrument link identifier."
    },
    {
      "action_name": "auto-unpack_device_error",
      "description": "解析仪器返回的错误状态",
      "description_en": "Unpack the error status returned by the instrument."
    },
    {
      "action_name": "auto-unpack_create_link_resp",
      "description": "解析创建仪器链路的响应",
      "description_en": "Unpack the response to instrument link creation."
    },
    {
      "action_name": "auto-unpack_device_write_resp",
      "description": "解析仪器写入操作响应",
      "description_en": "Unpack the response from an instrument write operation."
    },
    {
      "action_name": "auto-unpack_device_read_resp",
      "description": "解析仪器读取操作响应",
      "description_en": "Unpack the response from an instrument read operation."
    },
    {
      "action_name": "auto-unpack_device_read_stb_resp",
      "description": "解析状态字节读取响应",
      "description_en": "Unpack the response from a status-byte read."
    },
    {
      "action_name": "auto-unpack_device_docmd_resp",
      "description": "解析设备命令执行响应",
      "description_en": "Unpack the response from a device command execution."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化仪器通信会话",
      "description_en": "Initialize the instrument communication session."
    },
    {
      "action_name": "auto-finalize",
      "description": "结束仪器通信会话",
      "description_en": "Finalize the instrument communication session."
    },
    {
      "action_name": "auto-write_raw",
      "description": "向仪器写入原始数据",
      "description_en": "Write raw data to the instrument."
    },
    {
      "action_name": "auto-read_raw",
      "description": "从仪器读取原始数据",
      "description_en": "Read raw data from the instrument."
    },
    {
      "action_name": "auto-read_stb",
      "description": "读取仪器状态字节",
      "description_en": "Read the instrument status byte."
    },
    {
      "action_name": "auto-trigger",
      "description": "触发仪器执行操作或采集",
      "description_en": "Trigger the instrument to perform an operation or acquisition."
    },
    {
      "action_name": "auto-clear",
      "description": "清除仪器当前状态",
      "description_en": "Clear the current instrument state."
    },
    {
      "action_name": "auto-remote",
      "description": "将仪器置于远程控制状态",
      "description_en": "Put the instrument into remote control."
    },
    {
      "action_name": "auto-local",
      "description": "将仪器恢复为本地控制状态",
      "description_en": "Return the instrument to local control."
    },
    {
      "action_name": "auto-lock",
      "description": "锁定仪器控制权",
      "description_en": "Lock control of the instrument."
    },
    {
      "action_name": "auto-unlock",
      "description": "释放仪器控制锁",
      "description_en": "Unlock the instrument."
    }
  ]
}

